14: export function SiteControls() {
15:   const { locale, setLocale } = useI18n();
16:   const [isDark, setIsDark] = useState(false);
17: 
18:   useEffect(() => {
19:     const saved = localStorage.getItem("tea-theme");
20:     if (saved === "dark" || (!saved && window.matchMedia("(prefers-color-scheme: dark)").matches)) {
21:       document.documentElement.classList.add("dark");
22:       setIsDark(true);
23:     } else {
24:       document.documentElement.classList.remove("dark");
25:       setIsDark(false);
26:     }
27:   }, []);
28: 
29:   const toggleTheme = () => {
30:     const next = !document.documentElement.classList.contains("dark");
31:     document.documentElement.classList.toggle("dark", next);
32:     localStorage.setItem("tea-theme", next ? "dark" : "light");
33:     setIsDark(next);
34:   };
35: 
36:   return (
37:     <div className="inline-flex items-center gap-1.5">
38:       {/* 语言切换下拉菜单 */}
39:       <DropdownMenu>
40:         <DropdownMenuTrigger asChild>
41:           <Button
42:             variant="outline"
43:             size="sm"
44:             className="h-8 gap-1.5 px-2.5 font-medium"
45:             aria-label="Switch language"
46:           >
47:             <Languages className="size-3.5 text-muted-foreground" />
48:             <span>{locale === "en" ? "EN" : "中文"}</span>
49:           </Button>
50:         </DropdownMenuTrigger>
51:         <DropdownMenuContent align="end">
52:           <DropdownMenuItem onClick={() => setLocale("zh")}>
53:             <span>简体中文</span>
54:             {locale === "zh" && <Check className="size-3.5 text-primary" />}
55:           </DropdownMenuItem>
56:           <DropdownMenuItem onClick={() => setLocale("en")}>
57:             <span>English</span>
58:             {locale === "en" && <Check className="size-3.5 text-primary" />}
59:           </DropdownMenuItem>
60:         </DropdownMenuContent>
61:       </DropdownMenu>
62: 
63:       {/* 明暗主题切换图标按钮（带平滑旋转缩放动画） */}
64:       <Button
65:         variant="outline"
66:         size="icon"
67:         onClick={toggleTheme}
68:         aria-label={isDark ? "Switch to light mode" : "Switch to dark mode"}
69:         className="relative size-8"
70:       >
71:         <Sun className="size-4 rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0" />
72:         <Moon className="absolute size-4 rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100" />
73:       </Button>
74:     </div>
75:   );
76: }

